package com.siam.deviceinfo.helper;
import android.content.*;import android.os.*;import java.util.*;
public final class BatteryHelper { public static Map<String,String> read(Context c){Map<String,String> m=new LinkedHashMap<>();Intent i=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null){m.put("অবস্থা","অনুপলব্ধ");return m;}int level=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=i.getIntExtra(BatteryManager.EXTRA_SCALE,100),temp=i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,-1),health=i.getIntExtra(BatteryManager.EXTRA_HEALTH,0),status=i.getIntExtra(BatteryManager.EXTRA_STATUS,0);m.put("ব্যাটারি",level>=0?Math.round(level*100f/Math.max(1,scale))+"%":"অনুপলব্ধ");m.put("তাপমাত্রা",temp>=0?String.format(Locale.getDefault(),"%.1f °C",temp/10f):"অনুপলব্ধ");String[] hs={"unknown","unknown","good","overheat","dead","over voltage","failure","cold"};m.put("স্বাস্থ্য",health>=0&&health<hs.length?hs[health]:"অনুপলব্ধ");m.put("চার্জিং",status==BatteryManager.BATTERY_STATUS_CHARGING||status==BatteryManager.BATTERY_STATUS_FULL?"হ্যাঁ":"না / সংযোগ নেই");m.put("অবশিষ্ট সময়","Android থেকে নির্ভরযোগ্য পূর্বাভাস পাওয়া যায় না");return m;} }
